__d(function(g,_r,i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return o}}),Object.defineProperty(_e,"PACK",{enumerable:!0,get:function(){return e}});const e={idioma:'pt',tela:'Sonhos',autores:{oneirocritica:'Artemidoro de Daldis',macrobio:'Macr\xf3bio',edicaoPack:'Roger A. Pack',harrisMcCoy:'Daniel E. Harris-McCoy',hammondThonemann:'Martin Hammond e Peter Thonemann'},recibo:function({autor:e,obra:o,locus:s,quando:r}){return`${e}, ${o} ${s}, ${r}`},chamada:{neutra:"Voc\xea discutiu com algu\xe9m \xe0s sete da noite e sonhou com a mesma discuss\xe3o \xe0 meia-noite. Isso \xe9 recado, ou \xe9 o dia voltando? Antes de perguntar o que um sonho quer dizer, vem uma pergunta que quase nenhum app faz \u2014 e \xe9 ela que decide se h\xe1 alguma coisa a dizer.",enhypnion:"Pelo que voc\xea respondeu, o sonho devolveu o dia que voc\xea teve. Quem vai dormir com fome sonha que come; quem vai dormir com raiva do chefe sonha com o chefe. Isso tem nome, tem dono e tem quase dois mil anos \u2014 e a primeira coisa que o nome faz \xe9 tirar o peso de cima do seu sonho.",oneiros:"Pelo que voc\xea respondeu, n\xe3o foi o seu dia voltando: entrou no sonho gente, lugar ou cena que voc\xea n\xe3o viveu naquele dia. \xc9 a partir daqui que vem a segunda pergunta, a que quase ningu\xe9m faz \u2014 de quem \xe9 este sonho?"},explicacao:{neutra:"Dia infernal no trabalho, o chefe em cima o tempo todo, e \xe0 noite l\xe1 est\xe1 ele no sonho. De manh\xe3 a pessoa digita \"sonhar com chefe\" no Google e o primeiro site responde que \xe9 medo de autoridade. S\xf3 que o que aconteceu \xe0s cinco da tarde explica melhor.\n\nQuem separou essas duas coisas por escrito \u2014 o sonho que devolve o dia e o sonho que traz outra coisa \u2014 foi Artemidoro de Daldis, na Oneirocritica, s\xe9c. II d.C. S\xe3o cinco livros: o quarto \xe9 sobre m\xe9todo e o quinto \xe9 uma cole\xe7\xe3o de 95 sonhos com o desfecho registrado. N\xe3o \xe9 um dicion\xe1rio de s\xedmbolos; \xe9 um manual de como perguntar.\n\nEle tem uma palavra para cada tipo. Enhypnion (no grego \u2014 o sonho que espelha o que a pessoa est\xe1 vivendo) \xe9 o do faminto que sonha que come, o do sedento que sonha que bebe, o do medroso que v\xea o que teme, o de quem ama e sonha que est\xe1 com quem ama: os exemplos s\xe3o dele, em 1.2. Oneiros \xe9 o outro, o sonho significativo do que vir\xe1 (1.1).\n\nS\xf3 depois disso v\xeam as cinco esp\xe9cies, e elas respondem outra pergunta: de quem \xe9 o sonho \u2014 s\xf3 seu, de outra pessoa que voc\xea conhece, de voc\xeas dois, da sua cidade ou do mundo (1.2.45\u201355). Responda e o app diz em que gaveta o seu relato cai, com o par\xe1grafo do lado. Ele n\xe3o diz o que o sonho quer dizer: na conta de Artemidoro isso depende de quem \xe9 voc\xea, e ele lista em 1.9 o que precisaria saber antes.",enhypnion:"Dia infernal no trabalho, o chefe em cima o tempo todo, e \xe0 noite l\xe1 est\xe1 ele no sonho. De manh\xe3 vem a busca no Google, e o primeiro site responde que chefe em sonho \xe9 medo de autoridade. S\xf3 que o que aconteceu \xe0s cinco da tarde explica melhor: o sonho devolveu o dia.\n\nIsso tem nome desde o s\xe9c. II d.C. Artemidoro de Daldis, na Oneirocritica, chama de enhypnion (no grego \u2014 o sonho que espelha o que a pessoa est\xe1 vivendo) o sonho feito do agora. Os exemplos s\xe3o dele, em 1.2: o faminto sonha que come, o sedento que bebe, o medroso v\xea o que teme, quem ama sonha que est\xe1 com quem ama. Na conta dele, esse tipo n\xe3o anuncia nada \u2014 \xe9 espelho do que j\xe1 \xe9, n\xe3o aviso do que vem.\n\nA frase que separa os dois tipos est\xe1 em 1.1 e \xe9 curta: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\" As tradu\xe7\xf5es inglesas discordam sobre qual palavra usar para cada termo grego, e \xe9 por isso que este app fica com o grego: enhypnion para o sonho do que \xe9, oneiros para o do que vir\xe1.\n\nNada disso \xe9 veredito sobre a sua noite. \xc9 a gaveta em que a fonte p\xf5e o relato que voc\xea deu, com o par\xe1grafo do lado. Se amanh\xe3 voc\xea reparar melhor e responder diferente, a gaveta muda \u2014 e era assim que ele trabalhava mesmo: pelo relato inteiro e por quem relatou (1.9).",oneiros:"Tem sonho que o dia n\xe3o explica. Voc\xea n\xe3o pensou naquela pessoa, n\xe3o passou perto daquele lugar, n\xe3o estava com raiva nem com medo de nada \u2014 e mesmo assim a cena veio inteira, com gente, endere\xe7o e hora.\n\nPara esse, Artemidoro de Daldis usa outra palavra: oneiros (no grego \u2014 o sonho significativo do que vir\xe1), e ele a separa do enhypnion, que \xe9 o sonho feito do que a pessoa j\xe1 estava vivendo. A distin\xe7\xe3o est\xe1 na Oneirocritica 1.1\u20131.2, s\xe9c. II d.C., e a frase \xe9 esta: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\"\n\nCair desse lado n\xe3o quer dizer que o sonho anuncie o que voc\xea espera, nem coisa boa nem coisa ruim. Quer dizer s\xf3 isto, e s\xf3 pelo seu relato: ele n\xe3o \xe9 o seu dia voltando.\n\n\xc9 aqui que entram as cinco esp\xe9cies. Antes de qualquer s\xedmbolo, ele pergunta de quem \xe9 o sonho: s\xf3 seu, de outra pessoa que voc\xea conhece, de voc\xeas dois, da sua cidade ou do mundo (1.2.45\u201355). \xc9 pergunta estrutural, tirada do texto, e \xe9 a que o app faz a seguir \u2014 em vez de abrir um dicion\xe1rio de imagens."},especies:{idioi:{nome:'s\xf3 seu',oQueE:'O sonho \xe9 seu do come\xe7o ao fim: voc\xea \xe9 quem faz e quem passa por tudo, e ningu\xe9m mais entra na cena com papel.',exemplo:'Voc\xea est\xe1 atrasado, corre, perde o \xf4nibus e perde a entrevista \u2014 e n\xe3o tem mais ningu\xe9m ali.'},allotrioi:{nome:'de outra pessoa',oQueE:'O sonho \xe9 sobre outra pessoa, e \xe9 gente que voc\xea conhece: sua m\xe3e, seu chefe, seu ex. Voc\xea est\xe1 l\xe1 como quem assiste.',exemplo:'Sua m\xe3e entra numa casa que voc\xea nunca viu, e voc\xea fica parado na porta, olhando.'},koina:{nome:'de voc\xeas dois',oQueE:'Voc\xea e mais algu\xe9m, juntos na mesma cena, os dois com papel no que acontece.',exemplo:'Voc\xea e a pessoa com quem voc\xea dorme discutem dentro de um carro parado, e os dois falam.'},demosia:{nome:'da sua cidade',oQueE:'O sonho n\xe3o \xe9 de ningu\xe9m em particular: \xe9 do lugar que \xe9 de todo mundo \u2014 a pra\xe7a, a rua, o porto, o templo.',exemplo:'A pra\xe7a do centro cheia de gente que voc\xea n\xe3o conhece, e alguma coisa acontecendo ali no meio.'},kosmika:{nome:'do mundo',oQueE:'O c\xe9u e o tempo: o que aparece l\xe1 em cima e pega todo mundo junto.',exemplo:'O c\xe9u fica vermelho no meio da tarde e a rua inteira para para olhar.'}},especieTexto:e=>`Pelo que voc\xea respondeu, o sonho \xe9 ${e.nome} \u2014 ${e.transliteracao} (${e.grego}), na lista das cinco. ${e.oQueE}`,semEspecie:{faltaResposta:'Ainda falta uma resposta para dizer de quem \xe9 o sonho \u2014 e o app prefere dizer que falta a escolher uma das cinco no chute.',pessoaDesconhecida:"Voc\xea disse que n\xe3o conhece a pessoa que apareceu, e aqui o app para. A segunda das cinco esp\xe9cies \xe9 definida com todas as letras como outra pessoa CONHECIDA de quem sonhou (1.2.45). O que Artemidoro faz com o desconhecido esta pesquisa n\xe3o leu \u2014 e empurrar o seu relato para a gaveta mais parecida seria inventar m\xe9todo em nome dele.",foraDaLista:"As cinco esp\xe9cies dizem de QUEM o sonho \xe9: voc\xea, outra pessoa que voc\xea conhece, voc\xeas dois, a cidade, o mundo (1.2.45\u201355). Voc\xea respondeu que n\xe3o \xe9 nada disso, e a lista acaba a\xed \u2014 n\xe3o existe uma sexta gaveta na fonte, e o app n\xe3o abre uma. Fica sem esp\xe9cie, e fica dito."},vocabulario:{enhypnion:{nome:'o sonho que devolve o dia',oQueE:'Espelha o que a pessoa est\xe1 vivendo enquanto dorme: a fome, o medo, a saudade, a briga que n\xe3o saiu da cabe\xe7a. Na conta de Artemidoro, esse tipo n\xe3o anuncia nada \u2014 e os exemplos s\xe3o dele.'},oneiros:{nome:'o sonho que traz outra coisa',oQueE:'O sonho significativo do que vir\xe1. \xc9 o que sobra quando o dia n\xe3o explica a cena.'},theorematikoi:{nome:'o sonho direto',oQueE:'Acontece exatamente como foi visto. O exemplo \xe9 dele: um homem sonhou com um naufr\xe1gio, e o naufr\xe1gio veio como no sonho. S\xf3 d\xe1 para saber depois, o que \xe9 justamente o problema.'},allegorikoi:{nome:'o sonho aleg\xf3rico',oQueE:'Diz uma coisa por meio de outra. As cinco esp\xe9cies s\xe3o subdivis\xf5es deste \u2014 n\xe3o do sonho em geral.'},horama:{nome:'a vis\xe3o',oQueE:'Uma vis\xe3o ligada aos sonhos significativos. A defini\xe7\xe3o exata n\xe3o chegou clara at\xe9 n\xf3s, e o app diz isso em vez de completar o que falta.'},chrematismos:{nome:'o sonho em que algu\xe9m fala',oQueE:'Uma pessoa ou uma divindade fala e instrui quem dorme. Esta pesquisa leu a entrada em resumo, n\xe3o a passagem inteira \u2014 e por isso a descri\xe7\xe3o para aqui.'},phantasma:{nome:'a imagem do limiar',oQueE:'A imagem estranha que aparece na beira do sono, sem conte\xfado de futuro. Esta pesquisa leu a entrada em resumo, n\xe3o a passagem inteira \u2014 e por isso a descri\xe7\xe3o para aqui.'}},perguntas:{diaAnterior:{pergunta:'O que apareceu no sonho \xe9 o que voc\xea viveu naquele dia? Fome, medo, saudade, a briga das sete, o assunto que n\xe3o saiu da sua cabe\xe7a.',opcoes:{sim:'Sim \u2014 o meu dia est\xe1 ali dentro',nao:'N\xe3o \u2014 veio coisa que eu n\xe3o vivi'}},quemApareceu:{pergunta:'De quem \xe9 o sonho? Pense em quem tem papel na cena, n\xe3o em quem passa no fundo.',opcoes:{'so-voce':'S\xf3 eu','outra-pessoa':'Outra pessoa, e eu olhando','voce-e-outra':'Eu e mais algu\xe9m, os dois na cena','a-cidade':'A cidade: rua, pra\xe7a, um lugar que \xe9 de todo mundo','o-mundo':'O c\xe9u, o tempo, alguma coisa que pega todo mundo junto','nada-disso':'Nada disso'}},conheceQuemApareceu:{pergunta:'Voc\xea conhece essa pessoa na vida real?',opcoes:{sim:'Conhe\xe7o',nao:'N\xe3o conhe\xe7o'}},aindaComVoce:{pergunta:'O sonho continuou com voc\xea depois de acordar?',opcoes:{sim:'Continuou \u2014 passei o dia com aquilo',nao:'Passou assim que eu levantei'}}},perguntaDoApp:'Esta pergunta \xe9 do app, n\xe3o da fonte: nenhum texto antigo desta pesquisa a usa como crit\xe9rio. Ela serve para voc\xea reparar melhor \u2014 e n\xe3o muda a classifica\xe7\xe3o.',checklistIntro:'Antes de dizer o que qualquer imagem quer dizer, Artemidoro exige saber quem sonhou. A lista \xe9 dele, tem seis itens, e \xe9 o que separa o m\xe9todo dele de um dicion\xe1rio:',checklist:{identidade:'quem a pessoa \xe9',oficio:'o que ela faz da vida',nascimento:'de onde ela vem',dinheiro:'quanto ela tem',corpo:'como est\xe1 o corpo dela \u2014 este item est\xe1 na lista dele e o app n\xe3o usa: aqui n\xe3o se fala do corpo de ningu\xe9m. Fica citado para voc\xea poder conferir a lista inteira na fonte.',idade:'que idade ela tem'},porqueCamada:{enhypnion:'Voc\xea respondeu que o seu dia est\xe1 ali dentro, e \xe9 essa resposta que decide: pela pergunta de Artemidoro (1.2), o sonho que espelha o que a pessoa est\xe1 vivendo \xe9 o enhypnion.',oneiros:'Voc\xea respondeu que veio coisa que n\xe3o viveu naquele dia, e \xe9 essa resposta que decide: o sonho que n\xe3o espelha o agora \xe9 o que ele chama de oneiros (1.1).'},porqueEspecie:{'so-voce':'E voc\xea disse que s\xf3 voc\xea aparece na cena \u2014 \xe9 o que p\xf5e o relato na primeira das cinco esp\xe9cies.','outra-pessoa-conhecida':'E voc\xea disse que quem aparece \xe9 outra pessoa, que voc\xea conhece \u2014 \xe9 exatamente a defini\xe7\xe3o da segunda esp\xe9cie.','outra-pessoa-desconhecida':'Sobre a esp\xe9cie, o app parou: voc\xea disse que n\xe3o conhece a pessoa que apareceu, e a defini\xe7\xe3o da fonte pede que ela seja conhecida.','voce-e-outra':'E voc\xea disse que est\xe3o os dois na cena, cada um com papel \u2014 \xe9 o que a terceira esp\xe9cie abrange.','a-cidade':'E voc\xea disse que o sonho \xe9 do lugar que \xe9 de todo mundo \u2014 rua, pra\xe7a, porto, templo. \xc9 a quarta esp\xe9cie.','o-mundo':'E voc\xea disse que \xe9 o c\xe9u, o tempo, o que pega todo mundo junto \u2014 \xe9 a quinta.','nada-disso':'Sobre a esp\xe9cie, n\xe3o deu: as cinco dizem de quem o sonho \xe9, e voc\xea respondeu que n\xe3o \xe9 de nenhum deles.'},notaSubespecie:"Um detalhe que muda o tamanho da afirma\xe7\xe3o. As cinco esp\xe9cies s\xe3o subdivis\xf5es do sonho aleg\xf3rico \u2014 o que diz uma coisa por meio de outra (Oneirocritica 1.2.1). O outro tipo, o sonho direto, \xe9 o que acontece exatamente como foi visto: o exemplo do pr\xf3prio Artemidoro \xe9 um homem que sonhou com um naufr\xe1gio, e o naufr\xe1gio veio como no sonho. S\xf3 o desfecho separa um do outro, e desfecho o app n\xe3o tem. Por isso ele nomeia a esp\xe9cie pela pessoa que apareceu e n\xe3o decreta que o seu sonho \xe9 aleg\xf3rico.",notaNaoEDicionario:"Por que aqui n\xe3o tem dicion\xe1rio de s\xedmbolos. \"\xc1gua \xe9 emo\xe7\xe3o, cair \xe9 perder o controle, voar \xe9 liberdade\" n\xe3o est\xe1 em Artemidoro nem em fonte antiga nenhuma desta pesquisa \u2014 \xe9 dicion\xe1rio moderno, de revista. O m\xe9todo dele \xe9 o contr\xe1rio: o mesmo sonho muda de leitura conforme quem sonhou. O caso que ele registra \xe9 o mais limpo que existe \u2014 um escravo sonhou que tinha tr\xeas p\xeanis; foi libertado e, na alforria, passou a ter tr\xeas nomes, como todo cidad\xe3o romano (5.91). Num homem que j\xe1 era livre, o mesmo sonho n\xe3o diria nada disso. Em 1.79 \xe9 o dinheiro que muda tudo: a leitura depende do que o sonhador tem e do que a m\xe3e dele tem. \xc9 por isso que este app classifica o relato e n\xe3o vende significado de imagem.",notaLeituraDoApp:"O que \xe9 fonte e o que \xe9 app. A separa\xe7\xe3o entre o sonho que devolve o dia e o sonho que traz outra coisa \xe9 de Artemidoro de Daldis, Oneirocritica 1.1\u20131.2, s\xe9c. II d.C.; as cinco esp\xe9cies s\xe3o de 1.2.45\u201355; a exig\xeancia de saber quem sonhou \xe9 de 1.9. O que \xe9 nosso: as perguntas em portugu\xeas de hoje, a ordem em que elas aparecem e uma delas inteira \u2014 a de o sonho ter continuado depois de acordar, que nenhum texto antigo desta pesquisa autoriza como crit\xe9rio e que, por isso, n\xe3o decide nada.",notaDiscordancia:e=>'enhypnion'===e.camada?"Suas duas respostas puxam para lados diferentes: voc\xea disse que o seu dia est\xe1 ali dentro e, ao mesmo tempo, que o sonho continuou com voc\xea depois de acordar. O app n\xe3o desempata sozinho e n\xe3o esconde a discord\xe2ncia. Quem decide aqui \xe9 a pergunta de Artemidoro (1.2), porque a outra \xe9 nossa.":"Suas duas respostas puxam para lados diferentes: voc\xea disse que veio coisa que n\xe3o viveu naquele dia e, ao mesmo tempo, que o sonho passou assim que voc\xea levantou. O app n\xe3o desempata sozinho e n\xe3o esconde a discord\xe2ncia. Quem decide aqui \xe9 a pergunta de Artemidoro (1.2), porque a outra \xe9 nossa.",falta:{diaAnterior:{texto:"Falta a primeira pergunta, e \xe9 a que decide todo o resto: o que apareceu no sonho \xe9 o que voc\xea viveu naquele dia? Sem ela n\xe3o d\xe1 para saber se o sonho devolveu o seu dia ou trouxe outra coisa, e essas duas gavetas n\xe3o se parecem em nada. O app n\xe3o escolhe uma no seu lugar.",comoResolver:'Responda a primeira pergunta na tela de Sonhos.'},quemApareceu:{texto:"Falta dizer de quem \xe9 o sonho. As cinco esp\xe9cies de Artemidoro separam o sonho que \xe9 s\xf3 seu, o que \xe9 de outra pessoa, o de voc\xeas dois, o da cidade e o do mundo \u2014 e a diferen\xe7a entre elas \xe9 quem tem papel na cena. Sem essa resposta o app n\xe3o tem como escolher, e n\xe3o vai escolher por conta.",comoResolver:'Responda de quem \xe9 o sonho, na tela de Sonhos.'},conheceQuemApareceu:{texto:"Falta uma resposta curta, e ela \xe9 decisiva: voc\xea conhece a pessoa que apareceu? A segunda esp\xe9cie \xe9 definida como outra pessoa conhecida de quem sonhou (1.2.45), ent\xe3o conhecer ou n\xe3o conhecer troca a gaveta \u2014 e, quando n\xe3o conhece, esta pesquisa n\xe3o sabe qual \xe9 a gaveta.",comoResolver:'Responda se voc\xea conhece a pessoa, na tela de Sonhos.'}},verbatim:{definicao11:{texto:'A dream differs from a vision in that the one is indicative of what is to come, the other of what is.',parafrase:'Um dos dois aponta para o que vem; o outro, para o que j\xe1 \xe9. \xc9 a linha que separa o enhypnion do oneiros \u2014 e as tradu\xe7\xf5es inglesas discordam sobre qual palavra inglesa usar para cada termo grego, motivo pelo qual este app fica com o grego.',locus:'Artemidoro de Daldis, Oneirocritica 1.1, trad. inglesa de attalus.org',elisao:null},checklist19:{texto:"[the interpreter must know] the dreamer's identity, occupation, birth, financial status, \u2026 and age. Also, the nature of the dream itself must be examined accurately.",parafrase:'Antes de interpretar, \xe9 preciso saber quem a pessoa \xe9, o que ela faz da vida, de onde vem, quanto tem e que idade tem \u2014 e examinar o pr\xf3prio sonho com cuidado.',locus:'Artemidoro de Daldis, Oneirocritica 1.9, trad. inglesa de attalus.org',elisao:'A elis\xe3o nas retic\xeancias \xe9 nossa, e fica dita: ali a lista original traz um sexto item, o estado do corpo de quem sonha. Ele existe, est\xe1 na Oneirocritica 1.9 para quem quiser conferir, e o app n\xe3o o usa \u2014 porque n\xe3o fala do corpo de ningu\xe9m.'},prefacio:{texto:'I did not rely upon any simple theory of probabilities but rather on experience and the testimony of actual dream-fulfillments.',parafrase:'Ele se apresenta como quem juntou desfechos verificados, n\xe3o como quem recebeu revela\xe7\xe3o \u2014 e \xe9 isso que justifica o Livro V, com os 95 casos.',locus:'Artemidoro de Daldis, Oneirocritica, pref\xe1cio, trad. inglesa de attalus.org',elisao:null}},fontes:['Artemidoro de Daldis, Oneirocritica (\u1f48\u03bd\u03b5\u03b9\u03c1\u03bf\u03ba\u03c1\u03b9\u03c4\u03b9\u03ba\u03ac), s\xe9c. II d.C. \u2014 cinco livros, escritos por volta de 170\u2013200 d.C.; o Livro IV \xe9 sobre m\xe9todo e o Livro V re\xfane 95 sonhos com o desfecho registrado','Oneirocritica 1.1\u20131.2 \u2014 enhypnion e oneiros, a divis\xe3o entre sonho direto (theorematikoi) e aleg\xf3rico (allegorikoi), e as cinco esp\xe9cies do aleg\xf3rico em 1.2.45\u201355','Oneirocritica 1.9 \u2014 o que o int\xe9rprete precisa saber sobre quem sonhou antes de interpretar qualquer imagem','Oneirocritica 5.91 e 1.79 \u2014 os dois casos em que o mesmo sonho muda de leitura conforme a situa\xe7\xe3o de quem sonhou: o escravo que ganhou tr\xeas nomes e o pobre de m\xe3e rica','Tradu\xe7\xe3o inglesa parcial e gratuita em attalus.org/translate/artemidorus.html; edi\xe7\xe3o grega de refer\xeancia de Roger A. Pack (Teubner, 1963); tradu\xe7\xe3o e coment\xe1rio de Daniel E. Harris-McCoy (Oxford, 2012); tradu\xe7\xe3o de Martin Hammond com introdu\xe7\xe3o de Peter Thonemann (Oxford World\'s Classics, 2020)','Papiro Chester Beatty III (Egito, c. 1220 a.C.) e a s\xe9rie Ziq\u012bqu (tabuinhas de Assurban\xedpal, s\xe9c. VII a.C.) \u2014 os dicion\xe1rios de equival\xeancia fixa que vieram antes, e de que o m\xe9todo de Artemidoro \xe9 o contr\xe1rio','Macr\xf3bio, Commentarii in Somnium Scipionis, c. 430 d.C. \u2014 a SEGUNDA taxonomia de cinco esp\xe9cies da Antiguidade tardia, de outro autor e outro s\xe9culo; esta pesquisa n\xe3o conferiu os termos dele em edi\xe7\xe3o, e por isso o app n\xe3o os lista'],chrome:{kicker:'ANTES DE INTERPRETAR',titulo:'Este sonho diz alguma coisa?',abrir:'Abrir as perguntas',fechar:'Fechar',perguntasTitulo:'RESPONDA COM O QUE VOC\xca LEMBRA',rotuloDaFonte:'DA FONTE',rotuloDoApp:'PERGUNTA DO APP',limpar:'Recome\xe7ar as respostas',rotuloCamada:'A CAMADA',rotuloEspecie:'A ESP\xc9CIE',rotuloSemEspecie:'SEM ESP\xc9CIE',rotuloPorque:'POR QUE CAIU AQUI',rotuloDiscordancia:'AS DUAS RESPOSTAS PUXAM PARA LADOS DIFERENTES',explicacaoAbrir:'Por que esta pergunta vem antes',explicacaoFechar:'Fechar o texto',especiesAbrir:'Ver as cinco esp\xe9cies',especiesFechar:'Fechar as cinco',especiesTitulo:'AS CINCO, COMO ELAS EST\xc3O NA FONTE',exemploRotulo:'POR EXEMPLO',ressalvasAbrir:'Ler as ressalvas e a bibliografia',ressalvasFechar:'Fechar as ressalvas',checklistTitulo:'O QUE ELE EXIGIA SABER ANTES',verbatimTitulo:'NO ORIGINAL',verbatimParafrase:'EM CONVERSA',verbatimElisao:'SOBRE O CORTE',fontesTitulo:'DE ONDE ISTO VEM',compartilhar:'Compartilhar',copiado:'Texto copiado \u2014 \xe9 s\xf3 colar onde voc\xea quiser.',naoCopiou:'N\xe3o deu para copiar por aqui. Selecione o texto e copie \xe0 m\xe3o.',ponteIA:'A leitura por intelig\xeancia artificial desta tela \xe9 outra coisa, e ela \xe9 do app \u2014 n\xe3o de Artemidoro. Esta parte de cima s\xf3 diz em que gaveta o seu relato cai e o que a fonte exigiria saber antes de qualquer interpreta\xe7\xe3o.',marca:'Cosmic Guide'},textoCompartilhavel:e=>{if(!e||!e.disponivel)return null;const o=['Antes de perguntar o que um sonho quer dizer, vem outra pergunta: este sonho diz alguma coisa?','',`A camada: ${e.camadaNome} \u2014 ${e.camadaTransliteracao} (${e.camadaGrego})`,e.camadaRecibo];return e.especieNome?o.push('',`A esp\xe9cie: ${e.especieNome} \u2014 ${e.especieTransliteracao} (${e.especieGrego})`,e.especieRecibo):o.push('','A esp\xe9cie: n\xe3o deu para dizer \u2014 e o app prefere dizer isso a escolher uma das cinco no chute.'),o.push('','Cosmic Guide'),o.join('\n')}};var o=e},1614,[]);
__d(function(g,_r,i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return o}}),Object.defineProperty(_e,"PACK",{enumerable:!0,get:function(){return e}});const e={idioma:'es',tela:'Sue\xf1os',autores:{oneirocritica:'Artemidoro de Daldis',macrobio:'Macrobio',edicaoPack:'Roger A. Pack',harrisMcCoy:'Daniel E. Harris-McCoy',hammondThonemann:'Martin Hammond y Peter Thonemann'},recibo:function({autor:e,obra:o,locus:s,quando:n}){return`${e}, ${o} ${s}, ${n}`},chamada:{neutra:"Discutiste con alguien a las siete de la noche y so\xf1aste con la misma discusi\xf3n a medianoche. \xbfEso es un aviso, o es el d\xeda que vuelve? Antes de preguntar qu\xe9 quiere decir un sue\xf1o hay otra pregunta, y casi ninguna app la hace: es la que decide si hay algo que decir.",enhypnion:"Por lo que respondiste, el sue\xf1o te devolvi\xf3 el d\xeda que tuviste. Quien se acuesta con hambre sue\xf1a que come; quien se acuesta con rabia del jefe sue\xf1a con el jefe. Eso tiene nombre, tiene due\xf1o y tiene casi dos mil a\xf1os \u2014 y lo primero que hace ese nombre es quitarle peso a tu sue\xf1o.",oneiros:"Por lo que respondiste, no fue tu d\xeda volviendo: entr\xf3 en el sue\xf1o gente, un lugar o una escena que no viviste ese d\xeda. Desde aqu\xed viene la segunda pregunta, la que casi nadie hace: \xbfde qui\xe9n es este sue\xf1o?"},explicacao:{neutra:"D\xeda infernal en el trabajo, el jefe encima todo el tiempo, y de noche ah\xed est\xe1 \xe9l en el sue\xf1o. Por la ma\xf1ana la persona escribe \"so\xf1ar con el jefe\" en Google y el primer sitio responde que es miedo a la autoridad. Solo que lo que pas\xf3 a las cinco de la tarde lo explica mejor.\n\nQuien separ\xf3 esas dos cosas por escrito \u2014 el sue\xf1o que devuelve el d\xeda y el sue\xf1o que trae otra cosa \u2014 fue Artemidoro de Daldis, en la Oneirocritica, siglo II d.C. Son cinco libros: el cuarto es sobre m\xe9todo y el quinto es una colecci\xf3n de 95 sue\xf1os con el desenlace anotado. No es un diccionario de s\xedmbolos; es un manual de c\xf3mo preguntar.\n\n\xc9l tiene una palabra para cada tipo. Enhypnion (en griego \u2014 el sue\xf1o que refleja lo que la persona est\xe1 viviendo) es el del hambriento que sue\xf1a que come, el del sediento que sue\xf1a que bebe, el del miedoso que ve lo que teme, el de quien ama y sue\xf1a que est\xe1 con quien ama: los ejemplos son suyos, en 1.2. Oneiros es el otro, el sue\xf1o significativo de lo que vendr\xe1 (1.1).\n\nSolo despu\xe9s vienen las cinco especies, y responden otra pregunta: \xbfde qui\xe9n es el sue\xf1o \u2014 solo tuyo, de otra persona que conoces, de ustedes dos, de tu ciudad o del mundo (1.2.45\u201355)? Responde y la app dice en qu\xe9 caj\xf3n cae tu relato, con el p\xe1rrafo al lado. No dice qu\xe9 quiere decir el sue\xf1o: en la cuenta de Artemidoro eso depende de qui\xe9n eres t\xfa, y en 1.9 \xe9l enumera lo que habr\xeda que saber antes.",enhypnion:"D\xeda infernal en el trabajo, el jefe encima todo el tiempo, y de noche ah\xed est\xe1 \xe9l en el sue\xf1o. Por la ma\xf1ana viene la b\xfasqueda en Google, y el primer sitio responde que el jefe en un sue\xf1o es miedo a la autoridad. Solo que lo que pas\xf3 a las cinco de la tarde lo explica mejor: el sue\xf1o devolvi\xf3 el d\xeda.\n\nEso tiene nombre desde el siglo II d.C. Artemidoro de Daldis, en la Oneirocritica, llama enhypnion (en griego \u2014 el sue\xf1o que refleja lo que la persona est\xe1 viviendo) al sue\xf1o hecho del ahora. Los ejemplos son suyos, en 1.2: el hambriento sue\xf1a que come, el sediento que bebe, el miedoso ve lo que teme, quien ama sue\xf1a que est\xe1 con quien ama. En su cuenta, este tipo no anuncia nada \u2014 es espejo de lo que ya es, no aviso de lo que viene.\n\nLa frase que separa los dos tipos est\xe1 en 1.1 y es corta: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\" Las traducciones inglesas no coinciden sobre qu\xe9 palabra usar para cada t\xe9rmino griego, y por eso esta app se queda con el griego: enhypnion para el sue\xf1o de lo que es, oneiros para el de lo que vendr\xe1.\n\nNada de esto es un veredicto sobre tu noche. Es el caj\xf3n donde la fuente pone el relato que diste, con el p\xe1rrafo al lado. Si ma\xf1ana miras mejor y respondes distinto, el caj\xf3n cambia \u2014 y as\xed trabajaba \xe9l: por el relato entero y por quien lo cont\xf3 (1.9).",oneiros:"Hay sue\xf1os que el d\xeda no explica. No pensaste en esa persona, no pasaste cerca de ese lugar, no ten\xedas rabia ni miedo de nada \u2014 y aun as\xed la escena vino entera, con gente, direcci\xf3n y hora.\n\nPara ese, Artemidoro de Daldis usa otra palabra: oneiros (en griego \u2014 el sue\xf1o significativo de lo que vendr\xe1), y lo separa del enhypnion, que es el sue\xf1o hecho de lo que la persona ya estaba viviendo. La distinci\xf3n est\xe1 en la Oneirocritica 1.1\u20131.2, siglo II d.C., y la frase es esta: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\"\n\nCaer de ese lado no quiere decir que el sue\xf1o anuncie lo que esperas, ni algo bueno ni algo malo. Quiere decir solo esto, y solo por tu relato: no es tu d\xeda volviendo.\n\nAqu\xed entran las cinco especies. Antes de cualquier s\xedmbolo, \xe9l pregunta de qui\xe9n es el sue\xf1o: solo tuyo, de otra persona que conoces, de ustedes dos, de tu ciudad o del mundo (1.2.45\u201355). Es una pregunta estructural, sacada del texto, y es la que la app hace enseguida \u2014 en vez de abrir un diccionario de im\xe1genes."},especies:{idioi:{nome:'solo tuyo',oQueE:'El sue\xf1o es tuyo de principio a fin: t\xfa haces y t\xfa aguantas todo, y nadie m\xe1s entra en la escena con un papel.',exemplo:'Vas tarde, corres, pierdes el bus y pierdes la entrevista \u2014 y no hay nadie m\xe1s ah\xed.'},allotrioi:{nome:'de otra persona',oQueE:'El sue\xf1o es sobre otra persona, y es alguien que conoces: tu madre, tu jefe, tu ex. T\xfa est\xe1s ah\xed mirando.',exemplo:'Tu madre entra en una casa que nunca viste, y t\xfa te quedas parado en la puerta, mirando.'},koina:{nome:'de ustedes dos',oQueE:'T\xfa y alguien m\xe1s, juntos en la misma escena, los dos con papel en lo que pasa.',exemplo:'T\xfa y la persona con la que duermes discuten dentro de un coche parado, y hablan los dos.'},demosia:{nome:'de tu ciudad',oQueE:'El sue\xf1o no es de nadie en particular: es del lugar que es de todos \u2014 la plaza, la calle, el puerto, el templo.',exemplo:'La plaza del centro llena de gente que no conoces, y algo pasando ah\xed en medio.'},kosmika:{nome:'del mundo',oQueE:'El cielo y el tiempo: lo que aparece all\xe1 arriba y alcanza a todos a la vez.',exemplo:'El cielo se pone rojo a media tarde y la calle entera se para a mirar.'}},especieTexto:e=>`Por lo que respondiste, el sue\xf1o es ${e.nome} \u2014 ${e.transliteracao} (${e.grego}), en la lista de las cinco. ${e.oQueE}`,semEspecie:{faltaResposta:'Todav\xeda falta una respuesta para decir de qui\xe9n es el sue\xf1o \u2014 y la app prefiere decir que falta antes que elegir una de las cinco a ciegas.',pessoaDesconhecida:"Dijiste que no conoces a la persona que apareci\xf3, y aqu\xed la app se detiene. La segunda de las cinco especies est\xe1 definida con todas las letras como otra persona CONOCIDA de quien so\xf1\xf3 (1.2.45). Qu\xe9 hace Artemidoro con el desconocido, esta investigaci\xf3n no lo ley\xf3 \u2014 y empujar tu relato al caj\xf3n m\xe1s parecido ser\xeda inventar m\xe9todo en su nombre.",foraDaLista:"Las cinco especies dicen de QUI\xc9N es el sue\xf1o: t\xfa, otra persona que conoces, ustedes dos, la ciudad, el mundo (1.2.45\u201355). Respondiste que no es nada de eso, y la lista termina ah\xed \u2014 no hay un sexto caj\xf3n en la fuente, y la app no abre uno. Se queda sin especie, y queda dicho."},vocabulario:{enhypnion:{nome:'el sue\xf1o que devuelve el d\xeda',oQueE:'Refleja lo que la persona est\xe1 viviendo mientras duerme: el hambre, el miedo, la falta que le hace alguien, la pelea que no se le fue de la cabeza. En la cuenta de Artemidoro, este tipo no anuncia nada \u2014 y los ejemplos son suyos.'},oneiros:{nome:'el sue\xf1o que trae otra cosa',oQueE:'El sue\xf1o significativo de lo que vendr\xe1. Es lo que queda cuando el d\xeda no explica la escena.'},theorematikoi:{nome:'el sue\xf1o directo',oQueE:'Pasa exactamente como fue visto. El ejemplo es suyo: un hombre so\xf1\xf3 con un naufragio, y el naufragio vino como en el sue\xf1o. Solo se sabe despu\xe9s, que es justamente el problema.'},allegorikoi:{nome:'el sue\xf1o aleg\xf3rico',oQueE:'Dice una cosa por medio de otra. Las cinco especies son subdivisiones de este \u2014 no del sue\xf1o en general.'},horama:{nome:'la visi\xf3n',oQueE:'Una visi\xf3n ligada a los sue\xf1os significativos. La definici\xf3n exacta no lleg\xf3 clara hasta nosotros, y la app lo dice en vez de completar lo que falta.'},chrematismos:{nome:'el sue\xf1o en que alguien habla',oQueE:'Una persona o una divinidad habla e instruye a quien duerme. Esta investigaci\xf3n ley\xf3 la entrada en resumen, no el pasaje entero \u2014 y por eso la descripci\xf3n se detiene aqu\xed.'},phantasma:{nome:'la imagen del umbral',oQueE:'La imagen extra\xf1a que aparece al borde del sue\xf1o, sin contenido de futuro. Esta investigaci\xf3n ley\xf3 la entrada en resumen, no el pasaje entero \u2014 y por eso la descripci\xf3n se detiene aqu\xed.'}},perguntas:{diaAnterior:{pergunta:'\xbfLo que apareci\xf3 en el sue\xf1o es lo que viviste ese d\xeda? Hambre, miedo, la falta que te hace alguien, la pelea de las siete, el asunto que no se te fue de la cabeza.',opcoes:{sim:'S\xed \u2014 mi d\xeda est\xe1 ah\xed dentro',nao:'No \u2014 vino algo que no viv\xed'}},quemApareceu:{pergunta:'\xbfDe qui\xe9n es el sue\xf1o? Piensa en qui\xe9n tiene papel en la escena, no en qui\xe9n pasa por el fondo.',opcoes:{'so-voce':'Solo yo','outra-pessoa':'Otra persona, y yo mirando','voce-e-outra':'Yo y alguien m\xe1s, los dos en la escena','a-cidade':'La ciudad: la calle, la plaza, un lugar que es de todos','o-mundo':'El cielo, el tiempo, algo que alcanza a todos a la vez','nada-disso':'Nada de eso'}},conheceQuemApareceu:{pergunta:'\xbfConoces a esa persona en la vida real?',opcoes:{sim:'La conozco',nao:'No la conozco'}},aindaComVoce:{pergunta:'\xbfEl sue\xf1o sigui\xf3 contigo despu\xe9s de despertar?',opcoes:{sim:'Sigui\xf3 \u2014 pas\xe9 el d\xeda con eso',nao:'Se fue apenas me levant\xe9'}}},perguntaDoApp:'Esta pregunta es de la app, no de la fuente: ning\xfan texto antiguo de esta investigaci\xf3n la usa como criterio. Sirve para que mires mejor \u2014 y no cambia la clasificaci\xf3n.',checklistIntro:'Antes de decir qu\xe9 quiere decir cualquier imagen, Artemidoro exige saber qui\xe9n so\xf1\xf3. La lista es suya, tiene seis puntos, y es lo que separa su m\xe9todo de un diccionario:',checklist:{identidade:'qui\xe9n es la persona',oficio:'a qu\xe9 se dedica',nascimento:'de d\xf3nde viene',dinheiro:'cu\xe1nto tiene',corpo:'c\xf3mo est\xe1 su cuerpo \u2014 este punto est\xe1 en la lista de \xe9l y la app no lo usa: aqu\xed no se habla del cuerpo de nadie. Queda citado para que puedas comprobar la lista entera en la fuente.',idade:'qu\xe9 edad tiene'},porqueCamada:{enhypnion:'Respondiste que tu d\xeda est\xe1 ah\xed dentro, y es esa respuesta la que decide: por la pregunta de Artemidoro (1.2), el sue\xf1o que refleja lo que la persona est\xe1 viviendo es el enhypnion.',oneiros:'Respondiste que vino algo que no viviste ese d\xeda, y es esa respuesta la que decide: el sue\xf1o que no refleja el ahora es el que \xe9l llama oneiros (1.1).'},porqueEspecie:{'so-voce':'Y dijiste que solo t\xfa apareces en la escena \u2014 eso pone el relato en la primera de las cinco especies.','outra-pessoa-conhecida':'Y dijiste que quien aparece es otra persona, y que la conoces \u2014 es exactamente la definici\xf3n de la segunda especie.','outra-pessoa-desconhecida':'Sobre la especie, la app se detuvo: dijiste que no conoces a la persona que apareci\xf3, y la definici\xf3n de la fuente pide que sea conocida.','voce-e-outra':'Y dijiste que est\xe1n los dos en la escena, cada uno con papel \u2014 es lo que abarca la tercera especie.','a-cidade':'Y dijiste que el sue\xf1o es del lugar que es de todos \u2014 calle, plaza, puerto, templo. Es la cuarta especie.','o-mundo':'Y dijiste que es el cielo, el tiempo, lo que alcanza a todos a la vez \u2014 es la quinta.','nada-disso':'Sobre la especie, no sali\xf3: las cinco dicen de qui\xe9n es el sue\xf1o, y respondiste que no es de ninguno.'},notaSubespecie:"Un detalle que cambia el tama\xf1o de la afirmaci\xf3n. Las cinco especies son subdivisiones del sue\xf1o aleg\xf3rico \u2014 el que dice una cosa por medio de otra (Oneirocritica 1.2.1). El otro tipo, el sue\xf1o directo, es el que pasa exactamente como fue visto: el ejemplo del propio Artemidoro es un hombre que so\xf1\xf3 con un naufragio, y el naufragio vino como en el sue\xf1o. Solo el desenlace separa uno del otro, y desenlace la app no tiene. Por eso nombra la especie por quien apareci\xf3 y no decreta que tu sue\xf1o sea aleg\xf3rico.",notaNaoEDicionario:"Por qu\xe9 aqu\xed no hay diccionario de s\xedmbolos. \"El agua es emoci\xf3n, caer es perder el control, volar es libertad\" no est\xe1 en Artemidoro ni en ninguna fuente antigua de esta investigaci\xf3n \u2014 es diccionario moderno, de revista. Su m\xe9todo es lo contrario: el mismo sue\xf1o cambia de lectura seg\xfan qui\xe9n so\xf1\xf3. El caso que \xe9l registra es el m\xe1s limpio que hay \u2014 un esclavo so\xf1\xf3 que ten\xeda tres penes; fue liberado y, con la manumisi\xf3n, pas\xf3 a tener tres nombres, como todo ciudadano romano (5.91). En un hombre que ya era libre, el mismo sue\xf1o no dir\xeda nada de eso. En 1.79 es el dinero el que cambia todo: la lectura depende de lo que tiene quien so\xf1\xf3 y de lo que tiene su madre. Por eso esta app clasifica el relato y no vende significado de im\xe1genes.",notaLeituraDoApp:"Qu\xe9 es fuente y qu\xe9 es app. La separaci\xf3n entre el sue\xf1o que devuelve el d\xeda y el sue\xf1o que trae otra cosa es de Artemidoro de Daldis, Oneirocritica 1.1\u20131.2, siglo II d.C.; las cinco especies son de 1.2.45\u201355; la exigencia de saber qui\xe9n so\xf1\xf3 es de 1.9. Lo nuestro: las preguntas en espa\xf1ol de hoy, el orden en que aparecen y una de ellas entera \u2014 la de si el sue\xf1o sigui\xf3 contigo despu\xe9s de despertar, que ning\xfan texto antiguo de esta investigaci\xf3n autoriza como criterio y que, por eso, no decide nada.",notaDiscordancia:e=>'enhypnion'===e.camada?"Tus dos respuestas tiran para lados distintos: dijiste que tu d\xeda est\xe1 ah\xed dentro y, al mismo tiempo, que el sue\xf1o sigui\xf3 contigo despu\xe9s de despertar. La app no desempata sola y no esconde la contradicci\xf3n. Quien decide aqu\xed es la pregunta de Artemidoro (1.2), porque la otra es nuestra.":"Tus dos respuestas tiran para lados distintos: dijiste que vino algo que no viviste ese d\xeda y, al mismo tiempo, que el sue\xf1o se fue apenas te levantaste. La app no desempata sola y no esconde la contradicci\xf3n. Quien decide aqu\xed es la pregunta de Artemidoro (1.2), porque la otra es nuestra.",falta:{diaAnterior:{texto:"Falta la primera pregunta, y es la que decide todo lo dem\xe1s: \xbflo que apareci\xf3 en el sue\xf1o es lo que viviste ese d\xeda? Sin ella no hay forma de saber si el sue\xf1o te devolvi\xf3 el d\xeda o trajo otra cosa, y esos dos cajones no se parecen en nada. La app no elige uno por ti.",comoResolver:'Responde la primera pregunta en la pantalla de Sue\xf1os.'},quemApareceu:{texto:"Falta decir de qui\xe9n es el sue\xf1o. Las cinco especies de Artemidoro separan el sue\xf1o que es solo tuyo, el que es de otra persona, el de ustedes dos, el de la ciudad y el del mundo \u2014 y la diferencia entre ellas es qui\xe9n tiene papel en la escena. Sin esa respuesta la app no tiene c\xf3mo elegir, y no va a elegir por su cuenta.",comoResolver:'Responde de qui\xe9n es el sue\xf1o, en la pantalla de Sue\xf1os.'},conheceQuemApareceu:{texto:"Falta una respuesta corta, y es decisiva: \xbfconoces a la persona que apareci\xf3? La segunda especie est\xe1 definida como otra persona conocida de quien so\xf1\xf3 (1.2.45), as\xed que conocerla o no cambia el caj\xf3n \u2014 y, cuando no la conoces, esta investigaci\xf3n no sabe cu\xe1l es el caj\xf3n.",comoResolver:'Responde si conoces a la persona, en la pantalla de Sue\xf1os.'}},verbatim:{definicao11:{texto:'A dream differs from a vision in that the one is indicative of what is to come, the other of what is.',parafrase:'Uno de los dos apunta a lo que viene; el otro, a lo que ya es. Es la l\xednea que separa el enhypnion del oneiros \u2014 y las traducciones inglesas no coinciden sobre qu\xe9 palabra inglesa usar para cada t\xe9rmino griego, y por eso esta app se queda con el griego.',locus:'Artemidoro de Daldis, Oneirocritica 1.1, trad. inglesa de attalus.org',elisao:null},checklist19:{texto:"[the interpreter must know] the dreamer's identity, occupation, birth, financial status, \u2026 and age. Also, the nature of the dream itself must be examined accurately.",parafrase:'Antes de interpretar hay que saber qui\xe9n es la persona, a qu\xe9 se dedica, de d\xf3nde viene, cu\xe1nto tiene y qu\xe9 edad tiene \u2014 y examinar el propio sue\xf1o con cuidado.',locus:'Artemidoro de Daldis, Oneirocritica 1.9, trad. inglesa de attalus.org',elisao:'La elisi\xf3n de los puntos suspensivos es nuestra, y queda dicha: ah\xed la lista original trae un sexto punto, el estado del cuerpo de quien sue\xf1a. Existe, est\xe1 en Oneirocritica 1.9 para quien quiera comprobarlo, y la app no lo usa \u2014 porque aqu\xed no se habla del cuerpo de nadie.'},prefacio:{texto:'I did not rely upon any simple theory of probabilities but rather on experience and the testimony of actual dream-fulfillments.',parafrase:'\xc9l se presenta como alguien que junt\xf3 desenlaces comprobados, no como alguien que recibi\xf3 una revelaci\xf3n \u2014 y eso es lo que justifica el Libro V, con los 95 casos.',locus:'Artemidoro de Daldis, Oneirocritica, prefacio, trad. inglesa de attalus.org',elisao:null}},fontes:['Artemidoro de Daldis, Oneirocritica (\u1f48\u03bd\u03b5\u03b9\u03c1\u03bf\u03ba\u03c1\u03b9\u03c4\u03b9\u03ba\u03ac), siglo II d.C. \u2014 cinco libros, escritos alrededor del 170\u2013200 d.C.; el Libro IV es sobre m\xe9todo y el Libro V re\xfane 95 sue\xf1os con el desenlace anotado','Oneirocritica 1.1\u20131.2 \u2014 enhypnion y oneiros, la divisi\xf3n entre sue\xf1o directo (theorematikoi) y aleg\xf3rico (allegorikoi), y las cinco especies del aleg\xf3rico en 1.2.45\u201355','Oneirocritica 1.9 \u2014 lo que el int\xe9rprete necesita saber sobre quien so\xf1\xf3 antes de interpretar cualquier imagen','Oneirocritica 5.91 y 1.79 \u2014 los dos casos en que el mismo sue\xf1o cambia de lectura seg\xfan la situaci\xf3n de quien so\xf1\xf3: el esclavo que gan\xf3 tres nombres y el pobre de madre rica','Traducci\xf3n inglesa parcial y gratuita en attalus.org/translate/artemidorus.html; edici\xf3n griega de referencia de Roger A. Pack (Teubner, 1963); traducci\xf3n y comentario de Daniel E. Harris-McCoy (Oxford, 2012); traducci\xf3n de Martin Hammond con introducci\xf3n de Peter Thonemann (Oxford World\'s Classics, 2020)','Papiro Chester Beatty III (Egipto, c. 1220 a.C.) y la serie Ziq\u012bqu (tablillas de Asurbanipal, siglo VII a.C.) \u2014 los diccionarios de equivalencia fija que vinieron antes, y de los que el m\xe9todo de Artemidoro es lo contrario','Macrobio, Commentarii in Somnium Scipionis, c. 430 d.C. \u2014 la SEGUNDA taxonom\xeda de cinco especies de la Antig\xfcedad tard\xeda, de otro autor y otro siglo; esta investigaci\xf3n no comprob\xf3 sus t\xe9rminos en edici\xf3n, y por eso la app no los enumera'],chrome:{kicker:'ANTES DE INTERPRETAR',titulo:'\xbfEste sue\xf1o dice algo?',abrir:'Abrir las preguntas',fechar:'Cerrar',perguntasTitulo:'RESPONDE CON LO QUE RECUERDES',rotuloDaFonte:'DE LA FUENTE',rotuloDoApp:'PREGUNTA DE LA APP',limpar:'Volver a empezar las respuestas',rotuloCamada:'LA CAPA',rotuloEspecie:'LA ESPECIE',rotuloSemEspecie:'SIN ESPECIE',rotuloPorque:'POR QU\xc9 CAY\xd3 AQU\xcd',rotuloDiscordancia:'LAS DOS RESPUESTAS TIRAN PARA LADOS DISTINTOS',explicacaoAbrir:'Por qu\xe9 esta pregunta va primero',explicacaoFechar:'Cerrar el texto',especiesAbrir:'Ver las cinco especies',especiesFechar:'Cerrar las cinco',especiesTitulo:'LAS CINCO, TAL COMO EST\xc1N EN LA FUENTE',exemploRotulo:'POR EJEMPLO',ressalvasAbrir:'Leer las advertencias y la bibliograf\xeda',ressalvasFechar:'Cerrar las advertencias',checklistTitulo:'LO QUE \xc9L EXIG\xcdA SABER ANTES',verbatimTitulo:'EN EL ORIGINAL',verbatimParafrase:'EN CONVERSACI\xd3N',verbatimElisao:'SOBRE EL CORTE',fontesTitulo:'DE D\xd3NDE VIENE ESTO',compartilhar:'Compartir',copiado:'Texto copiado \u2014 solo falta pegarlo donde quieras.',naoCopiou:'No se pudo copiar por aqu\xed. Selecciona el texto y c\xf3pialo a mano.',ponteIA:'La lectura por inteligencia artificial de esta pantalla es otra cosa, y es de la app \u2014 no de Artemidoro. Esta parte de arriba solo dice en qu\xe9 caj\xf3n cae tu relato y qu\xe9 exigir\xeda saber la fuente antes de cualquier interpretaci\xf3n.',marca:'Cosmic Guide'},textoCompartilhavel:e=>{if(!e||!e.disponivel)return null;const o=['Antes de preguntar qu\xe9 quiere decir un sue\xf1o viene otra pregunta: \xbfeste sue\xf1o dice algo?','',`La capa: ${e.camadaNome} \u2014 ${e.camadaTransliteracao} (${e.camadaGrego})`,e.camadaRecibo];return e.especieNome?o.push('',`La especie: ${e.especieNome} \u2014 ${e.especieTransliteracao} (${e.especieGrego})`,e.especieRecibo):o.push('','La especie: no se pudo decir \u2014 y la app prefiere decirlo antes que elegir una de las cinco a ciegas.'),o.push('','Cosmic Guide'),o.join('\n')}};var o=e},1615,[]);
__d(function(g,_r,i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return t}}),Object.defineProperty(_e,"PACK",{enumerable:!0,get:function(){return e}});const e={idioma:'en',tela:'Dreams',autores:{oneirocritica:'Artemidorus of Daldis',macrobio:'Macrobius',edicaoPack:'Roger A. Pack',harrisMcCoy:'Daniel E. Harris-McCoy',hammondThonemann:'Martin Hammond and Peter Thonemann'},recibo:function({autor:e,obra:t,locus:o,quando:n}){return`${e}, ${t} ${o}, ${n}`},chamada:{neutra:"You had a fight with someone at seven in the evening and dreamed about the same fight at midnight. Is that a message, or is it just the day coming back? Before asking what a dream means, there is another question, and almost no app asks it: it is the one that decides whether there is anything to say at all.",enhypnion:"From what you answered, the dream handed you back the day you had. Go to bed hungry and you dream that you eat; go to bed furious at your boss and your boss shows up. That has a name, it has an owner, and it is almost two thousand years old \u2014 and the first thing the name does is take some weight off your dream.",oneiros:"From what you answered, this was not your day coming back: people, a place or a whole scene walked in that you did not live through that day. From here comes the second question, the one almost nobody asks: whose dream is this?"},explicacao:{neutra:"A brutal day at work, the boss on your back the whole time, and at night there he is in the dream. In the morning you type \"dreaming about my boss\" into Google and the first result says it is fear of authority. Except that what happened at five in the afternoon explains it better.\n\nThe person who first put those two things apart in writing \u2014 the dream that hands the day back and the dream that brings something else \u2014 was Artemidorus of Daldis, in the Oneirocritica, 2nd century AD. Five books: the fourth one is about method and the fifth is a collection of 95 dreams with the outcome written down. It is not a symbol dictionary; it is a manual on how to ask.\n\nHe has a word for each kind. Enhypnion (in Greek \u2014 the dream that mirrors what the person is living through) is the hungry one dreaming that he eats, the thirsty one dreaming that he drinks, the frightened one seeing what he fears, the one in love dreaming of the person he loves: the examples are his, in 1.2. Oneiros is the other one, the dream that is significant of what is to come (1.1).\n\nOnly after that come the five species, and they answer a different question: whose dream is it \u2014 yours alone, about someone you know, about the two of you, about your city, or about the world (1.2.45\u201355)? Answer and the app says which drawer your report lands in, with the paragraph next to it. It does not say what the dream means: on his account that depends on who you are, and in 1.9 he lists what would have to be known first.",enhypnion:"A brutal day at work, the boss on your back the whole time, and at night there he is in the dream. In the morning comes the Google search, and the first result says a boss in a dream is fear of authority. Except that what happened at five in the afternoon explains it better: the dream handed the day back to you.\n\nThis has had a name since the 2nd century AD. Artemidorus of Daldis, in the Oneirocritica, calls enhypnion (in Greek \u2014 the dream that mirrors what the person is living through) the dream made out of right now. The examples are his, in 1.2: the hungry man dreams that he eats, the thirsty one that he drinks, the frightened one sees what he fears, the one in love dreams of the person he loves. On his account this kind announces nothing \u2014 it is a mirror of what is, not notice of what comes.\n\nThe sentence that splits the two is in 1.1, and it is short: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\" English translations disagree about which word belongs to which Greek term, and that is why this app keeps the Greek: enhypnion for the dream of what is, oneiros for the dream of what is to come.\n\nNone of this is a verdict about your night. It is the drawer the source puts your report in, with the paragraph beside it. If tomorrow you look closer and answer differently, the drawer changes \u2014 and that is how he worked anyway: by the whole report and by the person who gave it (1.9).",oneiros:"Some dreams the day does not explain. You had not thought about that person, had not walked near that place, were not angry or scared of anything \u2014 and the scene still showed up whole, with people, an address and a time.\n\nFor that one Artemidorus of Daldis uses a different word: oneiros (in Greek \u2014 the dream that is significant of what is to come), and he keeps it apart from enhypnion, the dream made out of what the person was already living through. The distinction is in Oneirocritica 1.1\u20131.2, 2nd century AD, and the sentence is this one: \"A dream differs from a vision in that the one is indicative of what is to come, the other of what is.\"\n\nLanding on that side does not mean the dream announces what you are hoping for, or anything good or bad. It means only this, and only from your own report: it is not your day coming back.\n\nThis is where the five species come in. Before any symbol at all, he asks whose the dream is: yours alone, about someone you know, about the two of you, about your city, or about the world (1.2.45\u201355). It is a structural question, taken straight from the text, and it is the one the app asks next \u2014 instead of opening a dictionary of images."},especies:{idioi:{nome:'yours alone',oQueE:'The dream is yours from start to finish: you are the one acting and the one going through it, and nobody else has a part in the scene.',exemplo:'You are late, you run, you miss the bus and you miss the interview \u2014 and there is nobody else there.'},allotrioi:{nome:'about someone else',oQueE:'The dream is about another person, and it is someone you know: your mother, your boss, your ex. You are there as the one watching.',exemplo:'Your mother walks into a house you have never seen, and you stay at the door, watching.'},koina:{nome:'about the two of you',oQueE:'You and somebody else, together in the same scene, both of you with a part in what happens.',exemplo:'You and the person you sleep next to are arguing inside a parked car, and you are both talking.'},demosia:{nome:'about your city',oQueE:'The dream belongs to nobody in particular: it belongs to the place that belongs to everyone \u2014 the square, the street, the harbor, the temple.',exemplo:'The square downtown packed with people you do not know, and something happening in the middle of it.'},kosmika:{nome:'about the world',oQueE:'The sky and the weather: what shows up overhead and reaches everyone at once.',exemplo:'The sky turns red in the middle of the afternoon and the whole street stops to look.'}},especieTexto:e=>`From what you answered, the dream is ${e.nome} \u2014 ${e.transliteracao} (${e.grego}), on the list of five. ${e.oQueE}`,semEspecie:{faltaResposta:'One answer is still missing before anyone can say whose dream this is \u2014 and the app would rather say it is missing than pick one of the five blind.',pessoaDesconhecida:"You said you do not know the person who showed up, and this is where the app stops. The second of the five species is defined in so many words as another person KNOWN to the dreamer (1.2.45). What Artemidorus does with a stranger, this research never read \u2014 and pushing your report into the closest-looking drawer would be inventing method in his name.",foraDaLista:"The five species say WHOSE the dream is: you, someone you know, the two of you, the city, the world (1.2.45\u201355). You answered that it is none of those, and the list ends there \u2014 there is no sixth drawer in the source, and the app does not open one. It stays without a species, and that is stated."},vocabulario:{enhypnion:{nome:'the dream that hands the day back',oQueE:'It mirrors what the person is living through while asleep: the hunger, the fear, the missing someone, the fight that would not leave their head. On Artemidorus\u2019 account this kind announces nothing \u2014 and the examples are his.'},oneiros:{nome:'the dream that brings something else',oQueE:'The dream that is significant of what is to come. It is what is left over when the day does not explain the scene.'},theorematikoi:{nome:'the direct dream',oQueE:'It happens exactly as it was seen. The example is his: a man dreamed of a shipwreck, and the shipwreck came just as in the dream. You can only know afterward, which is precisely the problem.'},allegorikoi:{nome:'the allegorical dream',oQueE:'It says one thing by means of another. The five species are subdivisions of this one \u2014 not of dreams in general.'},horama:{nome:'the vision',oQueE:'A vision tied to the significant dreams. The exact definition did not survive clearly, and the app says so instead of filling in the gap.'},chrematismos:{nome:'the dream where someone speaks',oQueE:'A person or a god speaks and instructs the sleeper. This research read the entry in summary, not the full passage \u2014 so the description stops here.'},phantasma:{nome:'the image on the threshold',oQueE:'The strange image that shows up on the edge of sleep, with no content about the future. This research read the entry in summary, not the full passage \u2014 so the description stops here.'}},perguntas:{diaAnterior:{pergunta:'Is what showed up in the dream what you lived through that day? Hunger, fear, missing someone, the seven o\u2019clock fight, the thing that would not leave your head.',opcoes:{sim:'Yes \u2014 my day is right there in it',nao:'No \u2014 something came in that I did not live'}},quemApareceu:{pergunta:'Whose dream is it? Think about who has a part in the scene, not about who walks by in the background.',opcoes:{'so-voce':'Just me','outra-pessoa':'Someone else, with me watching','voce-e-outra':'Me and somebody else, both of us in the scene','a-cidade':'The city: a street, a square, a place that belongs to everyone','o-mundo':'The sky, the weather, something that reaches everyone at once','nada-disso':'None of that'}},conheceQuemApareceu:{pergunta:'Do you know that person in real life?',opcoes:{sim:'I know them',nao:'I do not know them'}},aindaComVoce:{pergunta:'Did the dream stay with you after you woke up?',opcoes:{sim:'It stayed \u2014 I carried it around all day',nao:'It was gone the moment I got up'}}},perguntaDoApp:'This question is the app\u2019s, not the source\u2019s: no ancient text in this research uses it as a criterion. It is here to help you look closer \u2014 and it does not change the sorting.',checklistIntro:'Before saying what any image means, Artemidorus demands knowing who did the dreaming. The list is his, it has six items, and it is what separates his method from a dictionary:',checklist:{identidade:'who the person is',oficio:'what they do for a living',nascimento:'where they come from',dinheiro:'how much they have',corpo:'the state of their body \u2014 this item is on his list and the app does not use it: nothing here speaks about anybody\u2019s body. It stays cited so you can check the full list in the source.',idade:'how old they are'},porqueCamada:{enhypnion:'You answered that your day is right there in it, and that answer is what decides: by Artemidorus\u2019 own question (1.2), the dream that mirrors what the person is living through is the enhypnion.',oneiros:'You answered that something came in that you did not live through that day, and that answer is what decides: the dream that does not mirror the present is what he calls oneiros (1.1).'},porqueEspecie:{'so-voce':'And you said only you show up in the scene \u2014 that puts the report in the first of the five species.','outra-pessoa-conhecida':'And you said the one who shows up is another person, someone you know \u2014 that is exactly the definition of the second species.','outra-pessoa-desconhecida':'On the species, the app stopped: you said you do not know the person who showed up, and the definition in the source asks for someone known.','voce-e-outra':'And you said both of you are in the scene, each with a part \u2014 that is what the third species covers.','a-cidade':'And you said the dream belongs to the place that belongs to everyone \u2014 street, square, harbor, temple. That is the fourth species.','o-mundo':'And you said it is the sky, the weather, the thing that reaches everyone at once \u2014 that is the fifth.','nada-disso':'On the species, nothing landed: the five say whose the dream is, and you answered that it is none of them.'},notaSubespecie:"One detail that changes the size of the claim. The five species are subdivisions of the allegorical dream \u2014 the one that says a thing by means of another (Oneirocritica 1.2.1). The other kind, the direct dream, is the one that happens exactly as it was seen: Artemidorus\u2019 own example is a man who dreamed of a shipwreck, and the shipwreck came just as in the dream. Only the outcome tells one from the other, and the app has no outcome. So it names the species by who showed up, and never rules that your dream is allegorical.",notaNaoEDicionario:"Why there is no symbol dictionary here. \"Water is emotion, falling is losing control, flying is freedom\" is not in Artemidorus and not in any ancient source in this research \u2014 it is a modern magazine dictionary. His method is the opposite: the same dream reads differently depending on who dreamed it. The case he records is the cleanest there is \u2014 an enslaved man dreamed he had three penises; he was freed, and with manumission he came to have three names, like every Roman citizen (5.91). In a man who was already free, the same dream would say none of that. In 1.79 it is money that changes everything: the reading depends on what the dreamer has and on what his mother has. That is why this app sorts the report and does not sell you the meaning of an image.",notaLeituraDoApp:"What is source and what is app. The split between the dream that hands the day back and the dream that brings something else is from Artemidorus of Daldis, Oneirocritica 1.1\u20131.2, 2nd century AD; the five species are from 1.2.45\u201355; the demand to know who did the dreaming is from 1.9. What is ours: the questions in today\u2019s English, the order they show up in, and one of them entirely \u2014 whether the dream stayed with you after waking, which no ancient text in this research authorizes as a criterion and which therefore decides nothing.",notaDiscordancia:e=>'enhypnion'===e.camada?"Your two answers pull in different directions: you said your day is right there in it and, at the same time, that the dream stayed with you after you woke up. The app does not break the tie on its own and does not hide the clash. What decides here is Artemidorus\u2019 question (1.2), because the other one is ours.":"Your two answers pull in different directions: you said something came in that you did not live through that day and, at the same time, that the dream was gone the moment you got up. The app does not break the tie on its own and does not hide the clash. What decides here is Artemidorus\u2019 question (1.2), because the other one is ours.",falta:{diaAnterior:{texto:"The first question is missing, and it is the one that decides everything else: is what showed up in the dream what you lived through that day? Without it there is no way to know whether the dream handed your day back or brought something else, and those two drawers look nothing alike. The app does not pick one for you.",comoResolver:'Answer the first question on the Dreams screen.'},quemApareceu:{texto:"Whose dream it is has not been answered yet. The five species of Artemidorus separate the dream that is yours alone, the one about someone else, the one about the two of you, the one about the city and the one about the world \u2014 and what tells them apart is who has a part in the scene. Without that answer the app has no way to choose, and it is not going to choose on its own.",comoResolver:'Answer whose dream it is, on the Dreams screen.'},conheceQuemApareceu:{texto:"One short answer is missing, and it decides the drawer: do you know the person who showed up? The second species is defined as another person known to the dreamer (1.2.45), so knowing them or not moves the report \u2014 and when you do not know them, this research does not know which drawer it goes in.",comoResolver:'Answer whether you know the person, on the Dreams screen.'}},verbatim:{definicao11:{texto:'A dream differs from a vision in that the one is indicative of what is to come, the other of what is.',parafrase:'One of the two points at what is coming; the other at what already is. That is the line between enhypnion and oneiros \u2014 and English translations disagree about which English word belongs to which Greek term, which is exactly why this app keeps the Greek.',locus:'Artemidorus of Daldis, Oneirocritica 1.1, English trans. from attalus.org',elisao:null},checklist19:{texto:"[the interpreter must know] the dreamer's identity, occupation, birth, financial status, \u2026 and age. Also, the nature of the dream itself must be examined accurately.",parafrase:'Before interpreting anything you have to know who the person is, what they do for a living, where they come from, how much they have and how old they are \u2014 and the dream itself has to be examined carefully.',locus:'Artemidorus of Daldis, Oneirocritica 1.9, English trans. from attalus.org',elisao:"The ellipsis is ours, and here it is out loud: at that point the original list carries a sixth item, the state of the dreamer's body. It exists, it sits in Oneirocritica 1.9 for anyone who wants to check it, and the app does not use it \u2014 because nothing here speaks about anybody's body."},prefacio:{texto:'I did not rely upon any simple theory of probabilities but rather on experience and the testimony of actual dream-fulfillments.',parafrase:'He presents himself as someone who collected verified outcomes, not as someone who received a revelation \u2014 and that is what Book V, with its 95 cases, is there to back up.',locus:'Artemidorus of Daldis, Oneirocritica, preface, English trans. from attalus.org',elisao:null}},fontes:['Artemidorus of Daldis, Oneirocritica (\u1f48\u03bd\u03b5\u03b9\u03c1\u03bf\u03ba\u03c1\u03b9\u03c4\u03b9\u03ba\u03ac), 2nd century AD \u2014 five books, written around 170\u2013200 AD; Book IV is about method and Book V collects 95 dreams with the outcome written down','Oneirocritica 1.1\u20131.2 \u2014 enhypnion and oneiros, the split between the direct dream (theorematikoi) and the allegorical one (allegorikoi), and the five species of the allegorical in 1.2.45\u201355','Oneirocritica 1.9 \u2014 what the interpreter has to know about the dreamer before interpreting any image','Oneirocritica 5.91 and 1.79 \u2014 the two cases where the same dream reads differently depending on the dreamer\u2019s situation: the enslaved man who gained three names, and the poor man with a rich mother','Partial free English translation at attalus.org/translate/artemidorus.html; standard Greek edition by Roger A. Pack (Teubner, 1963); translation and commentary by Daniel E. Harris-McCoy (Oxford, 2012); translation by Martin Hammond with an introduction by Peter Thonemann (Oxford World\u2019s Classics, 2020)','Papyrus Chester Beatty III (Egypt, c. 1220 BC) and the Ziq\u012bqu series (tablets from Ashurbanipal\u2019s library, 7th century BC) \u2014 the fixed-equivalence dictionaries that came before, and that Artemidorus\u2019 method is the opposite of','Macrobius, Commentarii in Somnium Scipionis, c. 430 AD \u2014 the SECOND fivefold taxonomy of late antiquity, by another author in another century; this research did not check his terms against an edition, which is why the app does not list them'],chrome:{kicker:'BEFORE INTERPRETING',titulo:'Does this dream say anything?',abrir:'Open the questions',fechar:'Close',perguntasTitulo:'ANSWER WITH WHAT YOU REMEMBER',rotuloDaFonte:'FROM THE SOURCE',rotuloDoApp:'THE APP\u2019S QUESTION',limpar:'Start the answers over',rotuloCamada:'THE LAYER',rotuloEspecie:'THE SPECIES',rotuloSemEspecie:'NO SPECIES',rotuloPorque:'WHY IT LANDED HERE',rotuloDiscordancia:'YOUR TWO ANSWERS PULL IN DIFFERENT DIRECTIONS',explicacaoAbrir:'Why this question comes first',explicacaoFechar:'Close the text',especiesAbrir:'See the five species',especiesFechar:'Close the five',especiesTitulo:'THE FIVE, EXACTLY AS THE SOURCE HAS THEM',exemploRotulo:'FOR INSTANCE',ressalvasAbrir:'Read the caveats and the bibliography',ressalvasFechar:'Close the caveats',checklistTitulo:'WHAT HE DEMANDED KNOWING FIRST',verbatimTitulo:'IN THE ORIGINAL',verbatimParafrase:'IN PLAIN WORDS',verbatimElisao:'ABOUT THE CUT',fontesTitulo:'WHERE THIS COMES FROM',compartilhar:'Share',copiado:'Text copied \u2014 paste it wherever you want.',naoCopiou:'Copying did not work here. Select the text and copy it by hand.',ponteIA:'The AI reading this screen does is a different thing, and it belongs to the app \u2014 not to Artemidorus. The part above only says which drawer your report lands in, and what the source would demand knowing before any interpretation at all.',marca:'Cosmic Guide'},textoCompartilhavel:e=>{if(!e||!e.disponivel)return null;const t=['Before asking what a dream means, another question comes first: does this dream say anything?','',`The layer: ${e.camadaNome} \u2014 ${e.camadaTransliteracao} (${e.camadaGrego})`,e.camadaRecibo];return e.especieNome?t.push('',`The species: ${e.especieNome} \u2014 ${e.especieTransliteracao} (${e.especieGrego})`,e.especieRecibo):t.push('','The species: it could not be said \u2014 and the app would rather say so than pick one of the five blind.'),t.push('','Cosmic Guide'),t.join('\n')}};var t=e},1616,[]);